	private static QueryRoot optimize(String query, Model data, List<String> expected) {
		TupleExpr original = parse(query);
		List<String> reference = evaluate(data, original);
		List<String> sortedExpected = new ArrayList<>(expected);
		Collections.sort(sortedExpected);
		assertEquals(sortedExpected, reference, "reference oracle disagrees with the hand-computed bag");
		QueryRoot optimized = new QueryRoot(original.clone());
		new SameTermFilterOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());
		assertEquals(reference, evaluate(data, optimized), "SameTermFilterOptimizer changed results\n" + optimized);
		// EXISTS probes are executor-mode dependent (a streaming probe substitutes the outer solution into the body,
		// a materialized probe evaluates the body unbound), so every mode must agree with the oracle.
		for (String mode : EXISTS_MODES) {
			assertEquals(reference, evaluate(data, withExistsMode(optimized, mode)),
					"SameTermFilterOptimizer changed results under " + mode + "\n" + optimized);
		}
		return optimized;
	}

	private static final List<String> EXISTS_MODES = List.of("streaming-correlated", "memoized-correlated",
			"materialized-hash");

	private static QueryRoot withExistsMode(QueryRoot root, String mode) {
		QueryRoot copy = root.clone();
		copy.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter node) {
				ValueExpr condition = node.getCondition();
				if (condition instanceof Not not) {
					condition = not.getArg();
				}
				if (condition instanceof Exists) {
					node.setStringMetricPlanned("optimizer.filterAlgorithmHint", mode);
				}
				super.meet(node);
			}
		});
		return copy;
	}

	private static boolean extensionAssigns(TupleExpr tupleExpr, String name) {
		boolean[] found = new boolean[1];
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ExtensionElem node) {
				if (node.getName().equals(name)) {
					found[0] = true;
				}
				super.meet(node);
			}
		});
		return found[0];
	}

	private static boolean containsEmptySet(TupleExpr tupleExpr) {
		boolean[] found = new boolean[1];
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(EmptySet node) {
				found[0] = true;
			}
		});
		return found[0];
	}

	private static boolean containsExtension(TupleExpr tupleExpr) {
		boolean[] found = new boolean[1];
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Extension node) {
				found[0] = true;
				super.meet(node);
			}
		});
		return found[0];
	}

	private static int sameTermCount(TupleExpr tupleExpr) {
		int[] count = new int[1];
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(SameTerm node) {
				count[0]++;
				super.meet(node);
			}
		});
		return count[0];
	}

	private static TupleExpr parse(String query) {
		return new SPARQLParser().parseQuery(PREFIXES + query, "urn:t:").getTupleExpr();
	}

	private static List<String> evaluate(Model data, TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				return new CloseableIteratorIteration<>(
						data.getStatements(subject, predicate, object, contexts).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		QueryRoot root = expression instanceof QueryRoot queryRoot ? queryRoot.clone()
				: new QueryRoot(expression.clone());
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = new StrictEvaluationStrategy(source, null).precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					Value value = bindings.getValue(name);
					if (value != null) {
						sorted.put(name, value.toString());
					}
				}
				StringBuilder builder = new StringBuilder();
				sorted.forEach((name, value) -> {
					if (builder.length() > 0) {
						builder.append('|');
					}
					builder.append(name).append('=').append(value);
				});
				rows.add(builder.toString());
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private static void add(Model model, String subject, String predicate, Value object) {
		model.add(VF.createIRI("urn:t:" + subject), VF.createIRI("urn:t:" + predicate), object);
	}
